import re

repo = {
    'api/users.py': 'def get_user(uid):\n    return db.find(uid)',
    'web/profile.js': 'async function fetchUser(id) { ... }',
    'svc/account.py': 'def retrieve_account_owner(acc):\n    ...',
}
pattern = re.compile(r'(get|fetch|load)_?[Uu]ser\w*')

for path, src in repo.items():
    for mt in pattern.finditer(src):
        print(path, '→', mt.group(0))
# api/users.py → get_user
# web/profile.js → fetchUser
# (retrieve_account_owner 는 못 찾는다 — 이건 시맨틱 검색의 몫)
